import json
import re
import subprocess
from pathlib import Path

from langchain_core.tools import tool

RECONCILER_SCRIPT = Path("/opt/wms/jobs/cycle_count_reconcile.py")
PYTHON_BIN = "/opt/wms/venv/bin/python"


def _build_command(zone_code: str, count_date: str, variance_threshold_pct: float) -> list:
    if not re.fullmatch(r"[A-Z0-9\-]{1,12}", zone_code):
        raise ValueError(f"invalid zone code: {zone_code}")
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", count_date):
        raise ValueError(f"invalid date: {count_date}")
    return [
        PYTHON_BIN,
        str(RECONCILER_SCRIPT),
        "--zone",
        zone_code,
        "--date",
        count_date,
        "--threshold",
        f"{variance_threshold_pct:.2f}",
        "--output",
        "json",
    ]


@tool
def run_cycle_count_reconciler(zone_code: str, count_date: str, variance_threshold_pct: float = 2.0) -> dict:
    try:
        command = _build_command(zone_code.upper(), count_date, variance_threshold_pct)
    except ValueError as exc:
        return {"ok": False, "error": str(exc)}
    try:
        completed = subprocess.run(
            command,
            capture_output=True,
            text=True,
            timeout=600,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "reconciliation job timed out after 600s"}
    if completed.returncode != 0:
        return {
            "ok": False,
            "exit_code": completed.returncode,
            "stderr": completed.stderr.strip()[-2000:],
        }
    try:
        summary = json.loads(completed.stdout)
    except json.JSONDecodeError:
        return {"ok": True, "raw_output": completed.stdout.strip()[-4000:]}
    variances = summary.get("variances", [])
    return {
        "ok": True,
        "zone_code": zone_code.upper(),
        "count_date": count_date,
        "skus_counted": summary.get("skus_counted", 0),
        "skus_over_threshold": len(variances),
        "variances": variances[:50],
    }
